    function __ESBMC_assume(bool) internal pure {}
    function run(uint a, address u) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (0)); require(a <= 1000000000000000000000000000000);
        require(address(this).balance >= a);
        c.addToBalance{value: a}(); if (__ESBMC_reverted()) return;
        uint balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        uint otherBefore = c.getBalance(u); if (__ESBMC_reverted()) return;
        c.addToBalance{value: 0}(); if (__ESBMC_reverted()) return;
        assert(c.getBalance(address(this)) == balBefore && address(c).balance == ethBefore && c.getBalance(u) == otherBefore && (u == address(this) ? c.getBalance(u) == balBefore : otherBefore == 0));
